export const vStockTakeReportInInventory = inventory.view("v_stock_take_report", {	tenantId: uuid("tenant_id"),
	stockTakeId: uuid("stock_take_id"),
	branchId: uuid("branch_id"),
	stockTakeStatus: text("stock_take_status"),
	result: text(),
	extraReason: text("extra_reason"),
	tagId: uuid("tag_id"),
	tagNo: varchar("tag_no", { length: 30 }),
	scannedCode: varchar("scanned_code", { length: 64 }),
	scannedAt: timestamp("scanned_at", { withTimezone: true, mode: 'string' }),
	scannedBy: uuid("scanned_by"),
	itemId: uuid("item_id"),
	purityId: uuid("purity_id"),
	grossWt: numeric("gross_wt"),
	netWt: numeric("net_wt"),
	tagStatus: text("tag_status"),
	tagBranchId: uuid("tag_branch_id"),
	counterId: uuid("counter_id"),
	boxId: uuid("box_id"),
	extraNote: text("extra_note"),
	duplicateCount: integer("duplicate_count"),
	lastDuplicateAt: timestamp("last_duplicate_at", { withTimezone: true, mode: 'string' }),
}).with({"securityInvoker":true}).as(sql`WITH expected AS ( SELECT s_1.tenant_id, s_1.id AS stock_take_id, t_1.id AS tag_id FROM inventory.stock_take s_1 JOIN inventory.tag t_1 ON t_1.tenant_id = s_1.tenant_id AND t_1.branch_id = s_1.branch_id AND (t_1.status = ANY (ARRAY['in_stock'::text, 'reserved'::text])) AND (s_1.counter_id IS NULL OR t_1.counter_id = s_1.counter_id) AND (s_1.box_id IS NULL OR t_1.box_id = s_1.box_id) ), r AS ( SELECT e.tenant_id, e.stock_take_id, e.tag_id, sc_1.id AS scan_id, true AS is_expected FROM expected e LEFT JOIN inventory.stock_take_scan sc_1 ON sc_1.tenant_id = e.tenant_id AND sc_1.stock_take_id = e.stock_take_id AND sc_1.tag_id = e.tag_id UNION ALL SELECT sc_1.tenant_id, sc_1.stock_take_id, sc_1.tag_id, sc_1.id, false FROM inventory.stock_take_scan sc_1 WHERE NOT (EXISTS ( SELECT 1 FROM expected x WHERE x.tenant_id = sc_1.tenant_id AND x.stock_take_id = sc_1.stock_take_id AND x.tag_id = sc_1.tag_id)) ) SELECT s.tenant_id, s.id AS stock_take_id, s.branch_id, s.status AS stock_take_status, CASE WHEN r.is_expected AND r.scan_id IS NULL THEN 'missing'::text ELSE sc.result END AS result, CASE WHEN r.scan_id IS NULL THEN NULL::text ELSE sc.extra_reason END AS extra_reason, r.tag_id, t.tag_no, sc.scanned_code, sc.scanned_at, sc.scanned_by, t.item_id, t.purity_id, t.gross_wt, t.net_wt, t.status AS tag_status, t.branch_id AS tag_branch_id, t.counter_id, t.box_id, sc.extra_note, sc.duplicate_count, sc.last_duplicate_at FROM r JOIN inventory.stock_take s ON s.tenant_id = r.tenant_id AND s.id = r.stock_take_id LEFT JOIN inventory.stock_take_scan sc ON sc.tenant_id = r.tenant_id AND sc.id = r.scan_id LEFT JOIN inventory.tag t ON t.tenant_id = r.tenant_id AND t.id = r.tag_id`);

export const vInvoiceBalanceInSales = sales.view("v_invoice_balance", {	tenantId: uuid("tenant_id"),
	branchId: uuid("branch_id"),
	invoiceId: uuid("invoice_id"),
	status: text(),
	netPayable: numeric("net_payable"),
	paidAtIssue: numeric("paid_at_issue"),
	receiptsTotal: numeric("receipts_total", { precision: 14, scale:  2 }),
	refundedTotal: numeric("refunded_total", { precision: 14, scale:  2 }),
	creditedToDue: numeric("credited_to_due", { precision: 14, scale:  2 }),
	paidAmount: numeric("paid_amount", { precision: 14, scale:  2 }),
	balanceDue: numeric("balance_due", { precision: 14, scale:  2 }),
	paymentStatus: text("payment_status"),
	cashTotal: numeric("cash_total", { precision: 14, scale:  2 }),
}).with({"securityInvoker":true}).as(sql`SELECT i.tenant_id, i.branch_id, i.id AS invoice_id, i.status, i.net_payable, i.paid_amount AS paid_at_issue, COALESCE(r.receipts_total, 0::numeric)::numeric(14,2) AS receipts_total, COALESCE(cn.refunded_total, 0::numeric)::numeric(14,2) AS refunded_total, COALESCE(d.due_reduced::numeric, 0::numeric)::numeric(14,2) AS credited_to_due, (i.paid_amount::numeric + COALESCE(r.receipts_total, 0::numeric))::numeric(14,2) AS paid_amount, CASE WHEN i.status = 'cancelled'::text THEN 0::numeric ELSE COALESCE(d.balance_due, i.balance_due)::numeric END::numeric(14,2) AS balance_due, CASE WHEN i.status = 'cancelled'::text THEN 'cancelled'::text WHEN COALESCE(d.balance_due, i.balance_due)::numeric = 0::numeric THEN 'paid'::text WHEN (i.paid_amount::numeric + COALESCE(r.receipts_total, 0::numeric)) = 0::numeric THEN 'unpaid'::text ELSE 'part_paid'::text END AS payment_status, (i.cash_amount::numeric + COALESCE(r.cash_total, 0::numeric))::numeric(14,2) AS cash_total FROM sales.invoice i LEFT JOIN sales.invoice_due d ON d.tenant_id = i.tenant_id AND d.invoice_id = i.id LEFT JOIN LATERAL ( SELECT sum(pr.total::numeric) AS receipts_total, sum(( SELECT COALESCE(sum(t.amount::numeric), 0::numeric) AS "coalesce" FROM sales.payment_receipt_tender t WHERE t.tenant_id = pr.tenant_id AND t.receipt_id = pr.id AND t.mode = 'cash'::text AND NOT (EXISTS ( SELECT 1 FROM sales.payment_receipt rv WHERE rv.tenant_id = pr.tenant_id AND rv.reverses_receipt_id = pr.id)))) AS cash_total FROM sales.payment_receipt pr WHERE pr.tenant_id = i.tenant_id AND pr.invoice_id = i.id) r ON true LEFT JOIN LATERAL ( SELECT sum(c.refund_amount::numeric) AS refunded_total FROM sales.credit_note c WHERE c.tenant_id = i.tenant_id AND c.invoice_id = i.id) cn ON true`);

